1	//! Standalone, executable regression target for external-plugin dispatch.
2	//!
3	//! Unlike the tests under `tests/derive/`, this file is a self-contained test
4	//! target that does not depend on any private test module from a candidate
5	//! branch. It defines its own derived CLI and observes every result solely
6	//! through the public `clap::Parser` API via `Cli::try_parse_from` (argv0
7	//! included): successful structures, typed errors, and rendered help text.
8	//!
9	//! Scenario under test:
10	//! * root command `tool` with a declared `run` subcommand (alias `r`) and an
11	//!   external-subcommand catch-all for plugins;
12	//! * root-level default config path and repeatable `--define` items that only
13	//!   parse while the root command is active;
14	//! * every token at or after the external command name is captured verbatim,
15	//!   including option-like tokens, declared subcommand names, a second `--`,
16	//!   and empty strings;
17	//! * a root-level `--` forces the next token to be the external command name,
18	//!   while `--` after `run` only produces `run` trailing arguments;
19	//! * validation failures name the triggering token and the most specific
20	//!   command and never leave a partially populated match readable;
21	//! * root and `run` help succeed while required values are missing;
22	//! * a fixed sequence of success, failure, success, and help parses is
23	//!   mutually isolated.
24	#![cfg(feature = "derive")]
25	#![cfg(feature = "help")]
26	#![cfg(feature = "usage")]
27	
28	use clap::Args;
29	use clap::Parser;
30	use clap::Subcommand;
31	use clap::error::ErrorKind;
32	
33	fn parse_define(raw: &str) -> Result<String, String> {
34	    if raw.contains('=') {
35	        Ok(raw.to_owned())
36	    } else {
37	        Err(format!("invalid define `{raw}`: expected key=value"))
38	    }
39	}
40	
41	#[derive(Parser, Debug, PartialEq)]
42	#[command(
43	    name = "tool",
44	    about = "Root command dispatching to built-in and plugin subcommands",
45	    override_usage = "tool [OPTIONS] <COMMAND>"
46	)]
47	struct Cli {
48	    #[arg(
49	        long,
50	        global = true,
51	        default_value = "builtin.toml",
52	        value_name = "path"
53	    )]
54	    config: String,
55	    #[arg(long, global = true, value_name = "key=value", value_parser = parse_define)]
56	    define: Vec<String>,
57	    #[command(subcommand)]
58	    command: Commands,
59	}
60	
61	#[derive(Subcommand, Debug, PartialEq)]
62	enum Commands {
63	    #[command(about = "Run a job", alias = "r")]
64	    Run(RunArgs),
65	    #[command(external_subcommand)]
66	    External(Vec<String>),
67	}
68	
69	#[derive(Args, Debug, PartialEq)]
70	#[command(override_usage = "tool run [OPTIONS] --output <path> [-- <TRAILING>...]")]
71	struct RunArgs {
72	    #[arg(long, value_name = "path", required = true)]
73	    output: String,
74	    #[arg(last = true)]
75	    trailing: Vec<String>,
76	}
77	
78	fn parse(argv: &[&str]) -> Result<Cli, clap::Error> {
79	    Cli::try_parse_from(argv)
80	}
81	
82	fn external_ok(argv: &[&str]) -> (String, Vec<String>, Vec<String>) {
83	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
84	    let Commands::External(tokens) = cli.command else {
85	        panic!(
86	            "expected external subcommand for {argv:?}, got {:?}",
87	            cli.command
88	        );
89	    };
90	    assert!(
91	        !tokens.is_empty(),
92	        "external capture must always include the command name: {argv:?}"
93	    );
94	    (cli.config, cli.define, tokens)
95	}
96	
97	fn run_ok(argv: &[&str]) -> (String, Vec<String>, RunArgs) {
98	    let cli = parse(argv).unwrap_or_else(|err| panic!("expected success for {argv:?}: {err}"));
99	    let Commands::Run(run) = cli.command else {
100	        panic!("expected `run` parse for {argv:?}, got {:?}", cli.command);
101	    };
102	    (cli.config, cli.define, run)
103	}
104	
105	/// Render an error while dropping the optional backtrace appended by clap's
106	/// `debug` feature. The backtrace captures host paths and frame line numbers
107	/// and is not part of the user-facing help or error output under test.
108	fn rendered(err: &clap::Error) -> String {
109	    let text = err.to_string();
110	    match text.split_once("\nBacktrace:") {
111	        Some((head, _)) => head.trim_end().to_owned(),
112	        None => text,
113	    }
114	}
115	
116	fn fail_kind(argv: &[&str]) -> (ErrorKind, String) {
117	    match parse(argv) {
118	        Ok(cli) => panic!("expected failure for {argv:?}, got {cli:?}"),
119	        Err(err) => {
120	            let kind = err.kind();
121	            (kind, rendered(&err))
122	        }
123	    }
124	}
125	
126	// ---- successful external dispatch --------------------------------------
127	
128	#[test]
129	fn external_dispatch_uses_root_defaults() {
130	    let (config, define, tokens) = external_ok(&["tool", "plug", "arg"]);
131	    assert_eq!(config, "builtin.toml");
132	    assert_eq!(define, Vec::<String>::new());
133	    assert_eq!(tokens, vec!["plug", "arg"]);
134	}
135	
136	#[test]
137	fn explicit_config_overrides_default_and_defines_keep_order() {
138	    let (config, define, tokens) = external_ok(&[
139	        "tool",
140	        "--define",
141	        "a=1",
142	        "--config",
143	        "custom.toml",
144	        "--define",
145	        "b=2",
146	        "--define=c=3",
147	        "plug",
148	    ]);
149	    assert_eq!(config, "custom.toml");
150	    assert_eq!(define, vec!["a=1", "b=2", "c=3"]);
151	    assert_eq!(tokens, vec!["plug"]);
152	}
153	
154	#[test]
155	fn external_captures_name_and_every_following_token_verbatim() {
156	    let (_, _, tokens) = external_ok(&[
157	        "tool", "plug", "--flag", "run", "r", "--", "", "--config", "x",
158	    ]);
159	    assert_eq!(
160	        tokens,
161	        vec!["plug", "--flag", "run", "r", "--", "", "--config", "x"]
162	    );
163	}
164	
165	#[test]
166	fn help_and_version_like_tokens_after_name_are_data() {
167	    let (_, _, tokens) = external_ok(&["tool", "plug", "--help", "--version", "-h"]);
168	    assert_eq!(tokens, vec!["plug", "--help", "--version", "-h"]);
169	}
170	
171	#[test]
172	fn root_options_after_external_name_are_captured_not_stolen() {
173	    let (config, define, tokens) = external_ok(&[
174	        "tool",
175	        "--config",
176	        "custom.toml",
177	        "plug",
178	        "--config",
179	        "stolen.toml",
180	        "--define",
181	        "c=3",
182	    ]);
183	    assert_eq!(config, "custom.toml");
184	    assert_eq!(define, Vec::<String>::new());
185	    assert_eq!(
186	        tokens,
187	        vec!["plug", "--config", "stolen.toml", "--define", "c=3"]
188	    );
189	}
190	
191	#[test]
192	fn prefix_of_declared_command_is_external() {
193	    let (_, _, tokens) = external_ok(&["tool", "ru", "--output", "x"]);
194	    assert_eq!(tokens, vec!["ru", "--output", "x"]);
195	}
196	
197	// ---- root-level `--` ------------------------------------------------------
198	
199	#[test]
200	fn root_double_dash_uses_next_token_as_external_name() {
201	    // The token right after the root separator is the command name, even when
202	    // it looks like a flag; the second separator and empty string stay in order.
203	    let (config, define, tokens) =
204	        external_ok(&["tool", "--config", "c.toml", "--", "--flag", "x", "--", ""]);
205	    assert_eq!(config, "c.toml");
206	    assert_eq!(define, Vec::<String>::new());
207	    assert_eq!(tokens, vec!["--flag", "x", "--", ""]);
208	}
209	
210	#[test]
211	fn root_double_dash_can_name_double_dash_itself() {
212	    let (_, _, tokens) = external_ok(&["tool", "--", "--", "--"]);
213	    assert_eq!(tokens, vec!["--", "--"]);
214	}
215	
216	#[test]
217	fn root_double_dash_can_name_empty_command() {
218	    let (_, _, tokens) = external_ok(&["tool", "--", "", "rest"]);
219	    assert_eq!(tokens, vec!["", "rest"]);
220	
221	    let (_, _, tokens) = external_ok(&["tool", ""]);
222	    assert_eq!(tokens, vec![""]);
223	}
224	
225	#[test]
226	fn root_double_dash_routes_declared_names_to_external_capture() {
227	    let (_, _, tokens) = external_ok(&["tool", "--", "run", "--output"]);
228	    assert_eq!(tokens, vec!["run", "--output"]);
229	
230	    let (_, _, tokens) = external_ok(&["tool", "--", "r"]);
231	    assert_eq!(tokens, vec!["r"]);
232	}
233	
234	// ---- `run` (and alias `r`) ------------------------------------------------
235	
236	#[test]
237	fn run_requires_output_and_uses_defaults() {
238	    let (config, define, run) = run_ok(&["tool", "run", "--output", "out.txt"]);
239	    assert_eq!(config, "builtin.toml");
240	    assert_eq!(define, Vec::<String>::new());
241	    assert_eq!(
242	        run,
243	        RunArgs {
244	            output: "out.txt".to_owned(),
245	            trailing: vec![],
246	        }
247	    );
248	}
249	
250	#[test]
251	fn run_alias_r_behaves_identically_for_success() {
252	    let via_run = run_ok(&["tool", "run", "--output", "o", "--", "a", "--flag"]).2;
253	    let via_r = run_ok(&["tool", "r", "--output", "o", "--", "a", "--flag"]).2;
254	    assert_eq!(via_run, via_r);
255	    assert_eq!(via_run.output, "o");
256	    assert_eq!(via_run.trailing, vec!["a", "--flag"]);
257	}
258	
259	#[test]
260	fn run_double_dash_feeds_trailing_and_cannot_redispatch_externally() {
261	    for name in ["run", "r"] {
262	        let argv = [
263	            "tool",
264	            name,
265	            "--output",
266	            "out.txt",
267	            "--",
268	            "plug",
269	            "--config",
270	            "other.toml",
271	            "run",
272	            "--",
273	            "",
274	        ];
275	        let (config, define, run) = run_ok(&argv);
276	        assert_eq!(run.output, "out.txt", "{name}");
277	        assert_eq!(
278	            run.trailing,
279	            vec!["plug", "--config", "other.toml", "run", "--", ""],
280	            "{name}"
281	        );
282	        // `run`'s separator terminates root parsing as well: its tail must not
283	        // re-enter the root or the external catch-all.
284	        assert_eq!(config, "builtin.toml", "{name}");
285	        assert_eq!(define, Vec::<String>::new(), "{name}");
286	    }
287	}
288	
289	#[test]
290	fn globals_accepted_alongside_run_reach_root_state() {
291	    let (config, define, run) = run_ok(&[
292	        "tool", "run", "--config", "x.toml", "--output", "o", "--define", "k=v",
293	    ]);
294	    assert_eq!(config, "x.toml");
295	    assert_eq!(define, vec!["k=v"]);
296	    assert_eq!(run.output, "o");
297	}
298	
299	// ---- failures -------------------------------------------------------------
300	
301	#[test]
302	fn missing_output_fails_for_both_run_names_with_run_specific_context() {
303	    for argv in [&["tool", "run"][..], &["tool", "r"][..]] {
304	        let (kind, msg) = fail_kind(argv);
305	        assert_eq!(kind, ErrorKind::MissingRequiredArgument, "{argv:?}");
306	        assert!(msg.contains("--output"), "{argv:?}: {msg}");
307	        // The error must identify the most specific command, not the root.
308	        assert!(msg.contains("tool run"), "{argv:?}: {msg}");
309	        assert!(
310	            !msg.contains("tool [OPTIONS] <COMMAND>"),
311	            "{argv:?} unexpectedly used root usage:\n{msg}"
312	        );
313	    }
314	}
315	
316	#[test]
317	fn duplicate_output_fails_for_both_run_names() {
318	    for argv in [
319	        &["tool", "run", "--output", "a", "--output", "b"][..],
320	        &["tool", "r", "--output", "a", "--output", "b"][..],
321	    ] {
322	        let (kind, msg) = fail_kind(argv);
323	        assert_eq!(kind, ErrorKind::ArgumentConflict, "{argv:?}");
324	        assert!(msg.contains("--output"), "{argv:?}: {msg}");
325	        assert!(msg.contains("tool run"), "{argv:?}: {msg}");
326	    }
327	}
328	
329	#[test]
330	fn duplicate_root_config_fails_at_root() {
331	    let argv = ["tool", "--config", "a", "--config", "b", "plug"];
332	    let (kind, msg) = fail_kind(&argv);
333	    assert_eq!(kind, ErrorKind::ArgumentConflict);
334	    assert!(msg.contains("--config"), "{msg}");
335	    assert!(msg.contains("tool [OPTIONS] <COMMAND>"), "{msg}");
336	}
337	
338	#[test]
339	fn unknown_root_option_fails_on_triggering_token_before_external_name() {
340	    for argv in [
341	        &["tool", "--bogus", "plug"][..],
342	        &["tool", "--config", "c.toml", "--bogus", "plug"][..],
343	    ] {
344	        let (kind, msg) = fail_kind(argv);
345	        assert_eq!(kind, ErrorKind::UnknownArgument, "{argv:?}");
346	        assert!(msg.contains("--bogus"), "{argv:?}: {msg}");
347	        assert!(msg.contains("tool [OPTIONS] <COMMAND>"), "{argv:?}: {msg}");
348	    }
349	
350	    let (kind, msg) = fail_kind(&["tool", "-x", "plug"]);
351	    assert_eq!(kind, ErrorKind::UnknownArgument);
352	    assert!(msg.contains("-x"), "{msg}");
353	}
354	
355	#[test]
356	fn unknown_run_option_fails_within_run_context() {
357	    let argv = ["tool", "run", "--output", "o", "--bogus"];
358	    let (kind, msg) = fail_kind(&argv);
359	    assert_eq!(kind, ErrorKind::UnknownArgument);
360	    assert!(msg.contains("--bogus"), "{msg}");
361	    assert!(msg.contains("tool run"), "{msg}");
362	}
363	
364	#[test]
365	fn missing_option_value_fails_on_the_option() {
366	    for argv in [
367	        &["tool", "--config"][..],
368	        &["tool", "--define"][..],
369	        &["tool", "--config", "c.toml", "--define"][..],
370	    ] {
371	        let (kind, msg) = fail_kind(argv);
372	        assert_eq!(kind, ErrorKind::InvalidValue, "{argv:?}");
373	        let needle = if argv.last() == Some(&"--config") {
374	            "--config"
375	        } else {
376	            "--define"
377	        };
378	        assert!(msg.contains(needle), "{argv:?}: {msg}");
379	    }
380	}
381	
382	#[test]
383	fn invalid_define_fails_on_value_before_external_name() {
384	    for argv in [
385	        &["tool", "--define", "nokey", "plug"][..],
386	        &["tool", "--define=nokey"][..],
387	    ] {
388	        let (kind, msg) = fail_kind(argv);
389	        assert_eq!(kind, ErrorKind::ValueValidation, "{argv:?}");
390	        assert!(msg.contains("nokey"), "{argv:?}: {msg}");
391	        // The error names both the offending value and the argument it belongs to.
392	        assert!(msg.contains("--define"), "{argv:?}: {msg}");
393	    }
394	}
395	
396	#[test]
397	fn invalid_define_after_external_name_is_captured_as_data() {
398	    let (config, define, tokens) = external_ok(&["tool", "plug", "--define", "nokey"]);
399	    assert_eq!(config, "builtin.toml");
400	    assert_eq!(define, Vec::<String>::new());
401	    assert_eq!(tokens, vec!["plug", "--define", "nokey"]);
402	}
403	
404	// ---- help -----------------------------------------------------------------
405	
406	#[test]
407	fn root_help_succeeds_without_subcommand_or_required_values() {
408	    let err = parse(&["tool", "--help"]).unwrap_err();
409	    assert_eq!(err.kind(), ErrorKind::DisplayHelp);
410	    let help = rendered(&err);
411	    for needle in ["--config", "builtin.toml", "--define", "key=value", "run"] {
412	        assert!(help.contains(needle), "root help missing {needle}:\n{help}");
413	    }
414	    assert!(
415	        !help.contains("--output"),
416	        "run option leaked into root help:\n{help}"
417	    );
418	    assert!(!help.to_ascii_lowercase().contains("error"), "{help}");
419	}
420	
421	#[test]
422	fn run_help_succeeds_while_output_is_missing() {
423	    for argv in [&["tool", "run", "--help"][..], &["tool", "r", "--help"][..]] {
424	        let err = parse(argv).unwrap_err();
425	        assert_eq!(err.kind(), ErrorKind::DisplayHelp, "{argv:?}");
426	        let help = rendered(&err);
427	        assert!(help.contains("--output"), "{argv:?}: {help}");
428	        assert!(help.contains("tool run"), "{argv:?}: {help}");
429	        assert!(help.contains("TRAILING"), "{argv:?}: {help}");
430	        assert!(
431	            !help.to_ascii_lowercase().contains("error"),
432	            "{argv:?}: {help}"
433	        );
434	    }
435	}
436	
437	// ---- fixed-order isolation sequence ---------------------------------------
438	
439	#[test]
440	fn fixed_order_sequence_success_failure_success_help_is_isolated() {
441	    // Capture a clean baseline help up front; the trailing help requests must
442	    // render the same text after the intervening failure.
443	    let clean_root_help = rendered(&parse(&["tool", "--help"]).unwrap_err());
444	    let clean_run_help = rendered(&parse(&["tool", "run", "--help"]).unwrap_err());
445	
446	    // 1. External success: explicit root state plus verbatim plugin tokens.
447	    let (config, define, tokens) = external_ok(&[
448	        "tool",
449	        "--config",
450	        "custom.toml",
451	        "--define",
452	        "a=1",
453	        "plug",
454	        "--flag",
455	        "run",
456	        "--",
457	        "",
458	    ]);
459	    assert_eq!(config, "custom.toml");
460	    assert_eq!(define, vec!["a=1"]);
461	    assert_eq!(tokens, vec!["plug", "--flag", "run", "--", ""]);
462	
463	    // 2. Invalid root input fails categorically on the offending token.
464	    let err = parse(&["tool", "--define", "bogus", "plug"]).unwrap_err();
465	    assert_eq!(err.kind(), ErrorKind::ValueValidation);
466	    assert!(rendered(&err).contains("bogus"));
467	
468	    // 3. `run` success is unaffected by either preceding call: root defaults
469	    //    are restored and no earlier tokens leak into trailing.
470	    let (config, define, run) = run_ok(&["tool", "r", "--output", "o", "--", "z", "--config"]);
471	    assert_eq!(config, "builtin.toml");
472	    assert_eq!(define, Vec::<String>::new());
473	    assert_eq!(
474	        run,
475	        RunArgs {
476	            output: "o".to_owned(),
477	            trailing: vec!["z".to_owned(), "--config".to_owned()],
478	        }
479	    );
480	
481	    // 4. Help requests still succeed and carry no trace of the failed call.
482	    let root_help = parse(&["tool", "--help"]).unwrap_err();
483	    assert_eq!(root_help.kind(), ErrorKind::DisplayHelp);
484	    let root_help = rendered(&root_help);
485	    assert_eq!(root_help, clean_root_help);
486	    assert!(!root_help.contains("bogus"), "{root_help}");
487	    assert!(!root_help.contains("--output"), "{root_help}");
488	
489	    let run_help = parse(&["tool", "run", "--help"]).unwrap_err();
490	    assert_eq!(run_help.kind(), ErrorKind::DisplayHelp);
491	    let run_help = rendered(&run_help);
492	    assert_eq!(run_help, clean_run_help);
493	    assert!(!run_help.contains("bogus"), "{run_help}");
494	    assert!(run_help.contains("--output"), "{run_help}");
495	}
