    let (kind, msg) = fail_kind(&["tool", "serve"]);
    assert_eq!(kind, ErrorKind::DisplayHelpOnMissingArgumentOrSubcommand);
    assert!(msg.contains("tool serve"), "{msg}");
    assert!(msg.contains("worker"), "{msg}");
}

