// Small extension trait used only to keep the odd scratch expression above
// honest about needing a static string slice.
trait LeakStatic {
    fn leak_static(self) -> &'static str;
}

impl LeakStatic for String {
    fn leak_static(self) -> &'static str {
        Box::leak(self.into_boxed_str())
    }
}

