    let (kind, msg) = fail_kind(&["tool", "serve", "worker", "--port", "8080", "plug"]);
    assert_eq!(kind, ErrorKind::UnknownArgument);
    assert!(msg.contains("'plug'"), "{msg}");
    assert!(msg.contains("tool serve worker"), "{msg}");
}

